PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    MotorLatch : BOOL;
END_VAR

MotorLatch := FALSE;

IF EStop = FALSE THEN
    IF Start AND NOT Stop THEN
        MotorLatch := TRUE;
    ELSIF Stop THEN
        MotorLatch := FALSE;
    END_IF;
END_IF;

Motor := MotorLatch AND EStop;

END_PROGRAM

