PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Motor : BOOL;
END_VAR
VAR
    motor_state : BOOL;
END_VAR

// Initialize motor state
motor_state := FALSE;

IF NOT EStop THEN
    // Emergency stop is active, always off
    Motor := FALSE;
ELSIF Start AND NOT Stop THEN
    // Start takes precedence over Stop
    motor_state := TRUE;
ELSIF Stop THEN
    // Stop overrides Start
    motor_state := FALSE;
END_IF;

Motor := motor_state;

END_PROGRAM

