PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
END_VAR

CASE Level OF
    | .. LowLimit - 1 :
        PumpIn := TRUE;
        ValveOut := FALSE;
    | HighLimit :
        PumpIn := FALSE;
        ValveOut := TRUE;
    | .. HighLimit + 1 :
        PumpIn := FALSE;
        ValveOut := TRUE;
    ELSE
        PumpIn := FALSE;
        ValveOut := FALSE;
END_CASE;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    low_limit : INT := 10;
    high_limit : INT := 90;
END_VAR

IF Level >= high_limit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= low_limit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    PumpInTimer : TON;
END_VAR

// Turn on pump if level is below low limit
IF Level <= 10 THEN
    PumpIn := TRUE;
    PumpInTimer(IN := TRUE, PT := T#5s);
ELSE
    PumpIn := FALSE;
END_IF;

// Turn off pump if level is above high limit
IF Level >= 90 THEN
    PumpIn := FALSE;
END_IF;

// Always open valve if level is above high limit
IF Level >= 90 THEN
    ValveOut := TRUE;
ELSE
    ValveOut := FALSE;
END_IF;

// Prevent pump from running when level is above high limit
IF Level >= 90 AND PumpIn THEN
    PumpIn := FALSE;
END_IF;

END_PROGRAM

