PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    A_timer : TON;
    B_timer : TON;
END_VAR

// Door A opens if commanded and Door B is closed
IF OpenA_Cmd AND NOT DoorB THEN
    A_timer(IN := TRUE, PT := T#0s);
    DoorA := A_timer.Q;
ELSE
    DoorA := FALSE;
END_IF;

// Door B opens if commanded and Door A is closed
IF OpenB_Cmd AND NOT DoorA THEN
    B_timer(IN := TRUE, PT := T#0s);
    DoorB := B_timer.Q;
ELSE
    DoorB := FALSE;
END_IF;

END_PROGRAM

