        DoorA_TON(IN := FALSE, PT := T#0s);
        DoorB_TON(IN := TRUE, PT := T#0s);
    ELSE
        DoorA_TON(IN := FALSE, PT := T#0s);
        DoorB_TON(IN := FALSE, PT := T#0s);
    END_IF;
ELSIF DoorA AND NOT DoorB THEN
    IF OpenA_Cmd THEN
        DoorA_TON(IN := TRUE, PT := T#0s);
    ELSE
        DoorA_TON(IN := FALSE, PT := T#0s);
    END_IF;
    DoorB_TON(IN := FALSE, PT := T#0s);
ELSIF DoorB AND NOT DoorA THEN
    IF OpenB_Cmd THEN
        DoorB_TON(IN := TRUE, PT := T#0s);
    ELSE
        DoorB_TON(IN := FALSE, PT := T#0s);
    END_IF;
    DoorA_TON(IN := FALSE, PT := T#0s);
END_IF;

DoorA := DoorA_TON.Q;
DoorB := DoorB_TON.Q;
END_PROGRAM

