PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    OpenA_Allowed : BOOL;
    OpenB_Allowed : BOOL;
END_VAR

-- Determine if each door can open based on the conditions
IF NOT OpenA_Cmd AND OpenB_Cmd THEN
    -- Door A can open if B is open but A is not
    OpenA_Allowed := FALSE;
    OpenB_Allowed := TRUE;
ELSIF OpenA_Cmd AND NOT OpenB_Cmd THEN
    -- Door B can open if A is open but B is not
    OpenA_Allowed := TRUE;
    OpenB_Allowed := FALSE;
ELSIF NOT OpenA_Cmd AND NOT OpenB_Cmd THEN
    -- Both can close if neither is requested
    OpenA_Allowed := FALSE;
    OpenB_Allowed := FALSE;
ELSE
    -- Neither should open if both are requested
    OpenA_Allowed := FALSE;
    OpenB_Allowed := FALSE;
END_IF;

-- Assign the output states based on allowed open commands
DoorA := OpenA_Allowed;
DoorB := OpenB_Allowed;

END_PROGRAM

