CASE State OF
    0:
        NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        T_NS_G(IN := NS_G, PT := T#2s);
        T_EW_R(IN := EW_R, PT := T#1s);
        IF T_NS_G.Q AND T_EW_R.Q THEN
            State := 1;
        END_IF;

    1:
        NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        T_NS_Y(IN := NS_Y, PT := T#1s);
        T_EW_R(IN := EW_R, PT := T#1s);
        IF T_NS_Y.Q AND T_EW_R.Q THEN
            State := 2;
        END_IF;

    2:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        T_NS_R(IN := NS_R, PT := T#1s);
        T_EW_R(IN := EW_R, PT := T#1s);
        IF T_NS_R.Q AND T_EW_R.Q THEN
            State := 3;
        END_IF;

    3:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
        T_NS_R(IN := NS_R, PT := T#1s);
        T_EW_G(IN := EW_G, PT := T#2s);
        IF T_NS_R.Q AND T_EW_G.Q THEN
            State := 4;
        END_IF;

    4:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := TRUE; EW_R := FALSE;
        T_NS_R(IN := NS_R, PT := T#1s);
        T_EW_Y(IN := EW_Y, PT := T#1s);
        IF T_NS_R.Q AND T_EW_Y.Q THEN
            State := 5;
        END_IF;

    5:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        T_NS_R(IN := NS_R, PT := T#1s);
        T_EW_R(IN := EW_R, PT := T#1s);
        IF T_NS_R.Q AND T_EW_R.Q THEN
            State := 0;
        END_IF;
END_CASE;

