PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
    FillTimer : TON;
    HeatTimer : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1: // Fill
        IF Level >= LVL_HIGH THEN
            State := 2;
        END_IF;
        FillValve := TRUE;

    2: // Heat
        IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
            State := 3;
        END_IF;
        Heater := TRUE;
        Agitator := TRUE;

    3: // React
        IF HeatTimer.Q THEN
            State := 4;
        END_IF;
        HeatTimer(IN := TRUE, PT := PT_REACT);

    4: // Drain
        IF Level <= LVL_LOW THEN
            State := 0;
        END_IF;
        DrainValve := TRUE;
END_CASE;

// Safety conditions
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF Level < LIQ_MIN AND (Heater OR Agitator) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

// Outputs
FillValve := FillValve AND EStop;
Heater := Heater AND EStop;
Agitator := Agitator AND EStop;
DrainValve := DrainValve AND EStop;
END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
    T : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND EStop THEN
    CASE State OF
        0:
            IF Level >= LIQ_MIN THEN
                State := 1;
                T(IN := TRUE, PT := T#0s);
            END_IF;
        1:
            IF T.Q OR Level >= LVL_HIGH THEN
                State := 2;
                T(IN := TRUE, PT := T#0s);
            ELSE
                FillValve := TRUE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
        2:
            IF T.Q OR Temp >= TEMP_SET THEN
                State := 3;
                T(IN := TRUE, PT := T#0s);
            ELSE
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
        3:
            IF T.Q THEN
                State := 4;
                T(IN := TRUE, PT := T#0s);
            ELSE
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
        4:
            IF T.Q OR Level <= LVL_LOW THEN
                State := 0;
                T(IN := TRUE, PT := T#0s);
            ELSE
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := TRUE;
            END_IF;
    END_CASE;
END_IF;

FillValve := FALSE OR (State = 1 AND Level < LVL_HIGH);
Heater := FALSE OR ((State = 2 OR State = 3) AND Temp < TEMP_SET);
Agitator := FALSE OR ((State = 2 OR State = 3));
DrainValve := FALSE OR (State = 4 AND Level > LVL_LOW);

END_PROGRAM

