CASE State OF
    0:
        IF EStop OR StopPB THEN
            State := 0;
            MainK := FALSE;
            StarK := FALSE;
            DeltaK := FALSE;
        ELSIF StartPB AND EStop THEN
            State := 1;
            MainK := TRUE;
            StarK := TRUE;
            DeltaK := FALSE;
