        END_IF;

    1:
        IF NOT StarTimer.Q THEN
            State := 1;
            MainK := TRUE;
            StarK := TRUE;
            DeltaK := FALSE;
            StarTimer(IN := TRUE, PT := PT_STAR);
        ELSIF EStop OR StopPB THEN
            State := 0;
            MainK := FALSE;
            StarK := FALSE;
            DeltaK := FALSE;
        ELSIF StartPB AND EStop THEN
            State := 2;
            MainK := TRUE;
            StarK := FALSE;
            DeltaK := TRUE;
        END_IF;

    2:
        IF EStop OR StopPB THEN
            State := 0;
            MainK := FALSE;
            StarK := FALSE;
            DeltaK := FALSE;
        END_IF;
END_CASE;

