    CarRed : BOOL;
    PedWalk : BOOL;
END_VAR
VAR CONSTANT
    PT_GREEN : TIME := T#3s;
    PT_YELLOW : TIME := T#2s;
    PT_WALK : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
    GreenTimer : TON;
    YellowTimer : TON;
    WalkTimer : TON;
END_VAR

CASE State OF
    0: // Cars green
        CarGreen := TRUE;
        CarYellow := FALSE;
        CarRed := FALSE;
        PedWalk := FALSE;

        IF GreenTimer.Q THEN
            IF PedReq THEN
                State := 1;
                YellowTimer(IN := TRUE, PT := PT_YELLOW);
            END_IF;
        ELSE
            GreenTimer(IN := TRUE, PT := PT_GREEN);
        END_IF;

    1: // Cars yellow
        CarGreen := FALSE;
        CarYellow := TRUE;
        CarRed := FALSE;
        PedWalk := FALSE;

        IF YellowTimer.Q THEN
            State := 2;
            WalkTimer(IN := TRUE, PT := PT_WALK);
        END_IF;

    2: // Cars red / Ped walk
        CarGreen := FALSE;
        CarYellow := FALSE;
        CarRed := TRUE;
        PedWalk := TRUE;

        IF WalkTimer.Q THEN
            State := 0;
            GreenTimer(IN := TRUE, PT := PT_GREEN);
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
    FillTimer : TON;
    DrainTimer : TON;
END_VAR

CASE State OF
    0 : // Idle
        IF NOT EStop AND StartCycle AND Level < 90 THEN
            State := 1;
            FillTimer(IN := TRUE, PT := T#5s);
        END_IF;

    1 : // Filling
        IF EStop OR Level >= 90 THEN
            State := 0;
            Pump := FALSE;
        ELSIF FillTimer.Q THEN
            State := 2;
            Pump := FALSE;
            Valve := TRUE;
            DrainTimer(IN := TRUE, PT := T#5s);
        ELSE
            Pump := TRUE;
            Valve := FALSE;
        END_IF;

    2 : // Draining
        IF EStop OR Level <= 10 THEN
            State := 0;
            Pump := FALSE;
            Valve := FALSE;
        ELSIF DrainTimer.Q THEN
            State := 1;
            Pump := TRUE;
            Valve := FALSE;
        ELSE
            Pump := FALSE;
            Valve := TRUE;
        END_IF;
END_CASE

// Safety checks
ASSERT NOT (Pump AND Valve);
ASSERT NOT (Level >= 90 AND Pump);
ASSERT NOT (Level <= 10 AND Valve);

END_PROGRAM

