PROGRAM conveyor_seq
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
END_VAR
VAR
    State : INT := 0;
    PT_SEQ : TON;
END_VAR

IF NOT EStop THEN
    // Emergency stop overrides everything
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
ELSIF StopPB THEN
    // Stop button overrides start button
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
ELSIF StartPB AND (State = 0 OR State = 1) THEN
    // Start sequence begins
    State := 1;
    C1 := FALSE;
    C2 := TRUE;
    PT_SEQ(IN := TRUE, PT := T#2s);
ELSIF PT_SEQ.Q AND State = 1 THEN
    // Move to running state after delay
    State := 2;
    C1 := TRUE;
    C2 := TRUE;
END_IF;

END_PROGRAM

