        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF StartPB AND EStop THEN
            State := 1;
            PurgeTimer(IN := TRUE, PT := T#3s);
        END_IF;

    1: // Pre-purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF NOT PurgeTimer.Q THEN
            State := 2;
            IgnitionTimer(IN := TRUE, PT := T#2s);
        END_IF;

    2: // Ignition trial
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF NOT IgnitionTimer.Q AND Flame THEN
            State := 3;
        ELSIF NOT IgnitionTimer.Q AND NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

