VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR
VAR
    Lead : INT;
    PrevDemand : BOOL;
END_VAR

// Update edge detection for demand ending
PrevDemand := Demand;

// Safety checks: EStop overrides everything
IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    // Alternate lead on demand end
    IF NOT Demand AND PrevDemand THEN
        Lead := 1 - Lead;
    END_IF;

    // Assign pumps based on lead state
    Pump1 := (Lead = 0);
    Pump2 := (Lead = 1);

    // Ensure only one pump runs
    ASSERT NOT (Pump1 AND Pump2);
END_IF;

