    Pump2 := FALSE;
ELSIF NOT Demand AND PrevDemand THEN
    Lead := 1 - Lead; // Toggle lead on demand fall
END_IF;

CASE Lead OF
    0: Pump1 := Demand; Pump2 := FALSE;
