-- Detect falling edge of Demand
IF NOT PrevDemand AND Demand THEN
    -- Toggle Lead on rising edge of Demand
    Lead := 1 - Lead;
END_IF;

PrevDemand := Demand;

-- Safety conditions: only one pump can run at a time, and only when there's demand
Pump1 := EStop AND (NOT Demand OR (Lead = 0 AND NOT Pump2));
Pump2 := EStop AND (NOT Demand OR (Lead = 1 AND NOT Pump1));

